def parse_duration(s: str) -> int:
    hours, minutes, seconds = 0, 0, 0
    parts = s.split()
    for part in parts:
        if part.endswith('h'):
            hours = int(part[:-1])
        elif part.endswith('m'):
            minutes = int(part[:-1])
        elif part.endswith('s'):
            seconds = int(part[:-1])
    return hours * 3600 + minutes * 60 + seconds
