        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900
    }
    total = 0
    i = 0
    while i < len(s):
        if s[i] in roman_map:
            if i + 1 < len(s) and (s[i+1] in {'V', 'X'}):
                total += roman_map[s[i]] + roman_map[s[i+1]]
                i += 2
            else:
                total += roman_map[s[i]]
                i += 1
        else:
            i += 1
    return total
